import os, glob, re

def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        # Find the next (h*w + 1) lines that form the grid
        lines = t[m.end():].split('\n')
        content = lines[:h*w]
        try:
            if h != 1:
                for row_idx in range(h):
                    row = lines[m.end() + row_idx*w : m.end() + (row_idx+1)*w]
                    G[k + str(row_idx)] = [[int(x) for x in r.split()] for r in row]
            else:
                G[k] = [[int(x) for x in l.split()] for l in lines[m.end():m.end()+h*w] if l]
        except:
            pass
    return G

G = load()
print(f"Loaded {len(G)} grid(s)")
for key in G:
